  "modules.cloud.aws": {
    "en": "EC2 Linux and Windows desktops, and AgentCore.",
    "zh-CN": "EC2 Linux 与 Windows 桌面，以及 AgentCore。"
  },
  "modules.cloud.awsNote": {
    "en": "Uses your AWS CLI sign-in (run `aws login` first). Desktops have no open ports; PandaCode reaches them through Systems Manager, which needs the Session Manager plugin for screens.",
    "zh-CN": "使用您的 AWS CLI 登录（请先运行 `aws login`）。桌面不开放端口，PandaCode 通过 Systems Manager 连接；查看屏幕需要 Session Manager 插件。"
  },
  "modules.cloud.claudeHelp": {
    "en": "Run `claude setup-token` and paste the long-lived token it prints. Without one, PandaCode copies this computer’s Claude Code login to the machine before each run.",
    "zh-CN": "运行 `claude setup-token`，粘贴输出的长期令牌。未提供令牌时，PandaCode 会在每次运行前将此计算机的 Claude Code 登录复制到主机。"
  },
  "modules.cloud.cloudflare": {
    "en": "Deploys to Workers and Pages, and container sandboxes.",
    "zh-CN": "部署到 Workers、Pages 及容器沙箱。"
  },
  "modules.cloud.cloudflareNote": {
    "en": "Agents deploy with Wrangler using this token. Container sandboxes are a separate one-time setup that deploys a small PandaCode Worker; it needs Docker running and a Workers Paid plan.",
    "zh-CN": "智能体使用此令牌通过 Wrangler 部署。容器沙箱需要单独进行一次性设置，以部署小型 PandaCode Worker；需要运行 Docker 并订阅 Workers 付费套餐。"
  },
  "modules.cloud.connected": {
    "en": "Connected{detail}{sandboxes}",
    "zh-CN": "已连接{detail}{sandboxes}"
  },
  "modules.cloud.connectProvider": {
    "en": "Connect {name}",
    "zh-CN": "连接 {name}"
  },
  "modules.cloud.daytonaNote": {
    "en": "Create a key at app.daytona.io → Keys. Sandboxes stop after 15 idle minutes.",
    "zh-CN": "在 app.daytona.io → Keys 创建密钥。沙箱闲置 15 分钟后停止。"
  },
  "modules.cloud.docker": {
    "en": "Containers on this machine or any Docker host.",
    "zh-CN": "在此计算机或其他 Docker 主机上运行容器。"
  },
  "modules.cloud.dockerNote": {
    "en": "Runs each task in its own container (label or name prefix pandacode) — Docker, Podman, Apple Containers, or the lxc client (LXD/Incus, which uses its own configured remotes; Podman remote hosts take ssh://). For ssh:// and tcp:// hosts, that daemon is root-equivalent — only point at machines you trust. Containers keep their disk until deleted and use this machine’s or the host’s resources; nothing is billed.",
    "zh-CN": "每个任务在独立容器中运行（标签或名称前缀为 pandacode），支持 Docker、Podman、Apple Containers 或 lxc 客户端（LXD/Incus 使用自身配置的远程主机；Podman 远程主机使用 ssh://）。ssh:// 和 tcp:// 主机的守护进程拥有相当于 root 的权限，请仅连接可信主机。容器使用本机或主机的资源，磁盘保留至删除，不产生云服务账单。"
  },
  "modules.cloud.gcloud": {
    "en": "Deploys by agents: Cloud Run and Cloud Storage.",
    "zh-CN": "由智能体部署到 Cloud Run 和 Cloud Storage。"
  },
  "modules.cloud.gcloudNote": {
    "en": "Uses your installed gcloud CLI and its sign-in (run `gcloud auth login` first); PandaCode downloads nothing and stores only the project, region and zone.",
    "zh-CN": "使用已安装的 gcloud CLI 及其登录（请先运行 `gcloud auth login`）。PandaCode 不会下载任何内容，只保存项目、区域和可用区。"
  },
